# Plant data: only users who can see the plant. Deliberately NO platform clause, so the super
# admin can never read readings. Readings are append-only: no UPDATE/DELETE policy, and the
# runtime role loses those privileges entirely.
RLS_AND_GRANTS = """
ALTER TABLE readings ENABLE ROW LEVEL SECURITY;
CREATE POLICY readings_read ON readings FOR SELECT
    USING (company_id = app_company_id() AND app_can_see_plant(plant_id));
CREATE POLICY readings_insert ON readings FOR INSERT
    WITH CHECK (company_id = app_company_id() AND app_can_see_plant(plant_id));

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'smayaa_app') THEN
        REVOKE UPDATE, DELETE ON readings FROM smayaa_app;
    END IF;
END
$$;
"""


